out={}
s0=sha(S)
out["matrix_verification"]={"state":{"path":S,"sha256":s0},"validator":{"path":vcm,"sha256":sha(vcm)},
 "loop":run(["python3",vcm,S]),"require_complete":run(["python3",vcm,S,"--require-complete"])}
out["matrix_verification"]["state_sha256_after"]=sha(S)
f0=sha(F)
out["doc_verification"]={"inputs":{"targets":{"path":S,"sha256":s0},"references":{"path":F,"sha256":f0},"state":{"path":S,"sha256":s0},"repo_root":R},
 "validator":{"path":vsc,"sha256":sha(vsc)},
 "run":run(["python3",vsc,"--targets",S,"--references",F,"--state",S,"--repo-root",R])}
out["doc_verification"]["after"]={"state":sha(S),"references":sha(F)}
