out["G-source-citation"]=run(["python3",A,"--source-citation",F,"--state",S,"--repo-root",R])
out["G-knowledge-graph"]=run(["python3",A,"--knowledge-graph"])
pathlib.Path(os.environ.get("TMPDIR","/tmp")+"/evalgates1.json").write_text(json.dumps(out,ensure_ascii=False,indent=1))
for k,v in out.items():
    if "exit_code" in v: print(k,v["exit_code"],v["stdout"][:1500],v["stderr"][:500])
    else:
        for kk,vv in v.items():
            if isinstance(vv,dict) and "exit_code" in vv: print(k,kk,vv["exit_code"],vv["stdout"][:1500],vv["stderr"][:500])
